class ClassicalGnbSyslogCollectorConfigurator:
    def add_syslog(self, ne_log_name, ne_log_configuration):
        test_pc = self.tl_config_information_provider.get_test_pc(
            node_id=self.ne_id,
            node_type=self.ne_type)
        ssh_executor = {
            'host': test_pc.default_ssh_connection_details.addr,
            'user': test_pc.default_ssh_connection_details.username,
            'password': test_pc.default_ssh_connection_details.password}
        decorated_syslog_collector_configuration = {
            'name': f"btslog_{self.ne_type}_{self.ne_id}",
            'type': "btslog",
            'executor': ssh_executor}
        lmp_connection = self.tl_config_information_provider.get_lmp_connection(self.ne_id, self.ne_type)
        syslog_collector_configuration = {
            'name': f"{ne_log_name}",
            'type': "log_collection_classical_gnb_syslog",
            'executor': {
                'host': lmp_connection.addr,
                'user': lmp_connection.username,
                'password': lmp_connection.password
            },
            'collector': decorated_syslog_collector_configuration['name']}
        self._collector_configuration_data.append(decorated_syslog_collector_configuration)
        self._collector_configuration_data.append(syslog_collector_configuration)

        self._collector_configuration_data.add_mapping_entry(
            log_type='syslog',
            network_element=f'{self.ne_type}_{self.ne_id}',
            collector_configuration=syslog_collector_configuration)
